package com.mushafi.qa;
import android.app.*;import android.content.*;import android.graphics.*;import com.mushafi.app.*;import java.util.concurrent.atomic.*;
final class LaunchChecks {
 static void need(boolean yes,String message)throws Exception{if(!yes)throw new Exception(message);}
 static boolean color(Instrumentation i,LaunchHarnessActivity activity,int expected){AtomicBoolean found=new AtomicBoolean();i.runOnMainSync(()->{int w=Math.max(320,activity.root.getWidth()),h=Math.max(640,activity.root.getHeight());activity.root.measure(android.view.View.MeasureSpec.makeMeasureSpec(w,1073741824),android.view.View.MeasureSpec.makeMeasureSpec(h,1073741824));activity.root.layout(0,0,w,h);Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);activity.root.draw(new Canvas(b));found.set(b.getPixel(10,10)==expected);b.recycle();});return found.get();}
 static void waitHidden(LaunchScreen curtain)throws Exception{long end=System.currentTimeMillis()+2500;while(curtain.isShowing()&&System.currentTimeMillis()<end)Thread.sleep(60);need(!curtain.isShowing(),"curtain finishes after timing and readiness");}
 static void run(Instrumentation i)throws Exception{LaunchHarnessActivity activity=(LaunchHarnessActivity)i.startActivitySync(new Intent(i.getTargetContext(),LaunchHarnessActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));LaunchScreen[] screen={null};AtomicInteger dismissed=new AtomicInteger();try{
 i.runOnMainSync(()->{screen[0]=new LaunchScreen(activity,activity.root,dismissed::incrementAndGet,()->{});screen[0].show();screen[0].resume();});need(color(i,activity,LaunchScreen.BACKGROUND),"loading covers underlying content with brand color, no white surface");Thread.sleep(5200);need(screen[0].isShowing(),"slow page never uncovered after 5-second timer alone");i.runOnMainSync(()->screen[0].pageReady());waitHidden(screen[0]);need(dismissed.get()==1,"first ready frame dismissed once");need(color(i,activity,0xff244a9e),"underlying page visible after curtain");
 i.runOnMainSync(()->screen[0].show());Thread.sleep(4200);need(screen[0].isShowing(),"warm launch still covered before 5 seconds");i.runOnMainSync(()->screen[0].pause());Thread.sleep(1200);need(screen[0].isShowing(),"background does not complete visual loading timer");i.runOnMainSync(()->screen[0].resume());waitHidden(screen[0]);need(dismissed.get()==2,"warm launch fades once after remaining foreground time");
 i.runOnMainSync(()->{screen[0].show();screen[0].destroy();});Thread.sleep(300);need(!screen[0].isShowing()&&dismissed.get()==2,"destroy cancels callbacks and animations");
 }finally{i.runOnMainSync(()->{if(screen[0]!=null)screen[0].destroy();activity.finish();});}}
}
